package eds

import (
	"bytes"
	"fmt"
	"go/format"
	"go/token"
	"math"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/otfabric/go-ethernetip/cip"
)

// GenerateOptions configures [GenerateGo].
type GenerateOptions struct {
	// Package is the package name of the generated file; default "device".
	Package string
	// Source names the EDS file in the header comment.
	Source string
	// License, when set, is written as an SPDX-License-Identifier line
	// ("MIT"); the generated code is otherwise unlabelled, as its licence
	// is its owner's choice.
	License string
}

// GenerateGo generates Go source for the device an EDS describes:
//
//   - its identity as constants and its electronic key;
//   - a constant and a descriptor per parameter, with a range check, and
//     a type with named constants per enumerated parameter;
//   - per assembly its instance and size and, when its members are whole
//     octets of parameters with numeric types, a struct with Encode and
//     Decode methods;
//   - per I/O connection whose path names assembly points, a function that
//     returns its scanner.IOConfig.
//
// The output is gofmt-formatted and deterministic: the same file gives the
// same source. Validate the file first: GenerateGo fails on the errors that
// prevent generation and skips what it cannot express, saying so in a
// comment.
func GenerateGo(f *File, opts GenerateOptions) ([]byte, error) {
	if opts.Package == "" {
		opts.Package = "device"
	}
	if !token.IsIdentifier(opts.Package) {
		return nil, fmt.Errorf("eds: package name %q", opts.Package)
	}
	dev, err := f.Device()
	if err != nil {
		return nil, err
	}
	params, err := f.Params()
	if err != nil {
		return nil, err
	}
	asms, err := f.Assemblies()
	if err != nil {
		return nil, err
	}
	conns, err := f.Connections()
	if err != nil {
		return nil, err
	}
	g := &gen{names: map[string]bool{}, params: map[int]Param{}, asms: map[int]Assembly{}}
	for _, n := range []string{"VendorID", "DeviceType", "ProductCode", "MajorRevision", "MinorRevision", "ProductName", "Key", "ParamInfo"} {
		g.names[n] = true
	}
	for _, p := range params {
		g.params[p.Number] = p
	}
	for _, a := range asms {
		g.asms[a.Number] = a
	}
	g.header(dev, opts)
	g.identity(dev)
	g.paramDecls(params)
	g.assemblyDecls(asms)
	g.connectionDecls(conns)
	src, err := format.Source(g.buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("eds: generated code does not format: %w", err)
	}
	return src, nil
}

type gen struct {
	buf    bytes.Buffer
	names  map[string]bool
	params map[int]Param
	asms   map[int]Assembly
}

func (g *gen) p(format string, a ...any) { fmt.Fprintf(&g.buf, format, a...) }

// ident turns a name into an exported Go identifier and reserves the
// identifiers that forms (fmt formats with one %s, "%s" when none is given)
// derive from it, so that no two declarations of the file collide.
func (g *gen) ident(prefix, name string, n int, forms ...string) string {
	if len(forms) == 0 {
		forms = []string{"%s"}
	}
	id := prefix + camel(name)
	if id == prefix || !token.IsIdentifier(id) || token.IsKeyword(id) {
		id = prefix + strconv.Itoa(n)
	}
	free := func(id string) bool {
		for _, f := range forms {
			if g.names[fmt.Sprintf(f, id)] {
				return false
			}
		}
		return true
	}
	for k, base := 1, id; !free(id); k++ {
		if k == 1 {
			id = base + strconv.Itoa(n)
		} else {
			id = fmt.Sprintf("%s%d_%d", base, n, k)
		}
	}
	for _, f := range forms {
		g.names[fmt.Sprintf(f, id)] = true
	}
	return id
}

// camel joins the ASCII letters and digits of name, each run starting with
// an upper-case letter.
func camel(name string) string {
	var sb strings.Builder
	up := true
	for _, r := range name {
		if r > unicode.MaxASCII || !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			up = true
			continue
		}
		if up {
			r = unicode.ToUpper(r)
			up = false
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

func (g *gen) header(dev Device, opts GenerateOptions) {
	src := opts.Source
	if src == "" {
		src = "an EDS file"
	}
	g.p("// Code generated by go-ethernetip eds.GenerateGo from %s. DO NOT EDIT.\n\n", src)
	if opts.License != "" {
		g.p("// SPDX-License-Identifier: %s\n\n", strings.Map(func(r rune) rune {
			if r == '\n' || r == '\r' {
				return ' '
			}
			return r
		}, opts.License))
	}
	g.p("// Package %s describes %s (vendor %d, product code %d, revision %s),\n", opts.Package, goComment(dev.ProductName), dev.VendorID, dev.ProductCode, dev.Revision)
	g.p("// as its Electronic Data Sheet declares it.\n")
	g.p("package %s\n\n", opts.Package)
	g.p("import (\n\t\"encoding/binary\"\n\t\"fmt\"\n\t\"math\"\n\t\"time\"\n\n\t\"github.com/otfabric/go-ethernetip/cip\"\n\t\"github.com/otfabric/go-ethernetip/scanner\"\n)\n\n")
	g.p("// The imports every generated file has, whether it uses them or not.\nvar (\n\t_ = binary.LittleEndian\n\t_ = fmt.Errorf\n\t_ = math.Float32bits\n\t_ = time.Millisecond\n\t_ scanner.IOConfig\n)\n\n")
}

// goComment returns s for a line comment: control characters, byte order
// marks and invalid UTF-8, which Go source cannot carry, become spaces.
func goComment(s string) string {
	return strings.Map(func(r rune) rune {
		if r < 0x20 || r == 0x7F || r == '\uFEFF' || r == utf8.RuneError {
			return ' '
		}
		return r
	}, strings.ToValidUTF8(s, "\uFFFD"))
}

func (g *gen) identity(dev Device) {
	g.p("// Identity of the device ([Device] section).\nconst (\n")
	g.p("\tVendorID uint16 = %d\n", dev.VendorID)
	g.p("\tDeviceType cip.DeviceType = %d\n", uint16(dev.DeviceType))
	g.p("\tProductCode uint16 = %d\n", dev.ProductCode)
	g.p("\tMajorRevision uint8 = %d\n", dev.Revision.Major)
	g.p("\tMinorRevision uint8 = %d\n", dev.Revision.Minor)
	g.p("\tProductName = %q\n", dev.ProductName)
	g.p(")\n\n")
	g.p("// Key returns the electronic key that matches the device exactly.\n")
	g.p("func Key() cip.KeySegment {\n\treturn cip.KeySegment{VendorID: VendorID, DeviceType: uint16(DeviceType), ProductCode: ProductCode, Major: MajorRevision, Minor: MinorRevision}\n}\n\n")
}

// goType returns the Go type of a numeric data type.
func goType(t cip.DataType) (string, bool) {
	switch t {
	case cip.TypeBOOL, cip.TypeUSINT, cip.TypeBYTE:
		return "uint8", true
	case cip.TypeSINT:
		return "int8", true
	case cip.TypeINT:
		return "int16", true
	case cip.TypeDINT:
		return "int32", true
	case cip.TypeLINT:
		return "int64", true
	case cip.TypeUINT, cip.TypeWORD:
		return "uint16", true
	case cip.TypeUDINT, cip.TypeDWORD:
		return "uint32", true
	case cip.TypeULINT, cip.TypeLWORD:
		return "uint64", true
	case cip.TypeREAL:
		return "float32", true
	case cip.TypeLREAL:
		return "float64", true
	default:
		return "", false
	}
}

// literal returns v as a Go literal of type gt, or false.
func literal(v, gt string) (string, bool) {
	v = strings.TrimSpace(v)
	if v == "" {
		return "", false
	}
	if gt == "float32" || gt == "float64" {
		x, err := number(v)
		if err != nil || math.IsInf(x, 0) || math.IsNaN(x) || gt == "float32" && math.Abs(x) > math.MaxFloat32 {
			return "", false
		}
		return strconv.FormatFloat(x, 'g', -1, 64), true
	}
	bits := map[string]int{"int8": 8, "int16": 16, "int32": 32, "int64": 64, "uint8": 8, "uint16": 16, "uint32": 32, "uint64": 64}[gt]
	if strings.HasPrefix(gt, "u") {
		x, err := strconv.ParseUint(strings.TrimPrefix(strings.TrimPrefix(v, "0x"), "0X"), base(v), bits)
		if err != nil {
			return "", false
		}
		return strconv.FormatUint(x, 10), true
	}
	x, err := strconv.ParseInt(v, 0, bits)
	if err != nil {
		if u, err2 := strconv.ParseUint(strings.TrimPrefix(strings.TrimPrefix(v, "0x"), "0X"), 16, bits); base(v) == 16 && err2 == nil {
			// A hex literal of a signed type is its two's complement.
			return strconv.FormatInt(int64(u)<<(64-bits)>>(64-bits), 10), true
		}
		return "", false
	}
	return strconv.FormatInt(x, 10), true
}

func base(v string) int {
	if strings.HasPrefix(v, "0x") || strings.HasPrefix(v, "0X") {
		return 16
	}
	return 10
}

func (g *gen) paramDecls(params []Param) {
	if len(params) == 0 {
		return
	}
	g.p("// ParamInfo describes a parameter of the [Params] section.\n")
	g.p("type ParamInfo struct {\n\tNumber int\n\tName string\n\tUnits string\n\tType cip.DataType\n\tPath string\n}\n\n")
	for _, p := range params {
		id := g.ident("Param", p.Name, p.Number, "%s", "%sDefault", "Check%s")
		path := ""
		if p.Path != nil {
			path = p.Path.String()
		}
		g.p("// %s is Param%d, %q", id, p.Number, p.Name)
		if p.Help != "" {
			g.p(": %s", goComment(p.Help))
		}
		g.p(".\nvar %s = ParamInfo{Number: %d, Name: %q, Units: %q, Type: 0x%02X, Path: %q}\n\n", id, p.Number, p.Name, p.Units, uint8(p.Type), path)
		gt, ok := goType(p.Type)
		if !ok {
			continue
		}
		var checks []string
		if lit, ok := literal(p.Min, gt); ok && (!strings.HasPrefix(gt, "u") || lit != "0") {
			checks = append(checks, fmt.Sprintf("v < %s", lit))
		}
		if lit, ok := literal(p.Max, gt); ok {
			checks = append(checks, fmt.Sprintf("v > %s", lit))
		}
		if lit, ok := literal(p.Default, gt); ok {
			g.p("// %sDefault is the default value of %s.\nconst %sDefault %s = %s\n\n", id, id, id, gt, lit)
		}
		g.p("// Check%s reports whether v is within the range of %s.\n", id, id)
		g.p("func Check%s(v %s) error {\n", id, gt)
		if len(checks) > 0 {
			g.p("\tif %s {\n\t\treturn fmt.Errorf(\"%s: %%v out of range\", v)\n\t}\n", strings.Join(checks, " || "), id)
		}
		g.p("\treturn nil\n}\n\n")
		if len(p.Enum) == 0 || (gt == "float32" || gt == "float64") {
			continue
		}
		et := g.ident("", fieldName(p.Name, p.Number), p.Number, "%sValue") + "Value"
		g.p("// %s is an enumerated value of %s.\ntype %s %s\n\n", et, id, et, gt)
		g.p("// Values of %s.\nconst (\n", et)
		var cases []string
		seen := map[string]bool{}
		for i, ev := range p.Enum {
			lit, ok := literal(strconv.FormatInt(ev.Value, 10), gt)
			if !ok {
				continue
			}
			cn := g.ident(et, ev.Name, i)
			g.p("\t%s %s = %s\n", cn, et, lit)
			// A switch cannot repeat a constant: the first name of a
			// value is its String.
			if !seen[lit] {
				seen[lit] = true
				cases = append(cases, fmt.Sprintf("\tcase %s:\n\t\treturn %q\n", cn, ev.Name))
			}
		}
		g.p(")\n\n")
		g.p("// String returns the name of the value.\nfunc (v %s) String() string {\n\tswitch v {\n%s\t}\n\treturn fmt.Sprintf(\"%s(%%d)\", %s(v))\n}\n\n", et, strings.Join(cases, ""), et, gt)
	}
}

// layout returns the fields of an assembly whose members are whole octets
// of numeric parameters (or padding), or false.
type field struct {
	name   string
	gt     string
	offset int
	size   int
}

func (g *gen) layout(a Assembly) ([]field, int, bool) {
	if len(a.Members) == 0 {
		return nil, 0, false
	}
	var out []field
	off := 0
	// Encode is the method of the struct.
	used := map[string]bool{"Encode": true}
	for _, m := range a.Members {
		if m.Bits%8 != 0 {
			return nil, 0, false
		}
		if m.Ref == "" {
			off += m.Bits / 8
			continue
		}
		mm := reRef.FindStringSubmatch(m.Ref)
		if mm == nil || !strings.EqualFold(mm[1], "Param") {
			return nil, 0, false
		}
		n, _ := strconv.Atoi(mm[2])
		p, ok := g.params[n]
		if !ok {
			return nil, 0, false
		}
		gt, ok := goType(p.Type)
		if !ok || p.Type.Size()*8 != m.Bits {
			return nil, 0, false
		}
		base := fieldName(p.Name, n)
		name := base
		for k := 2; used[name]; k++ {
			name = fmt.Sprintf("%s%d", base, k)
		}
		used[name] = true
		out = append(out, field{name: name, gt: gt, offset: off, size: m.Bits / 8})
		off += m.Bits / 8
	}
	if a.Size > 0 && off != a.Size {
		return nil, 0, false
	}
	return out, off, true
}

func fieldName(name string, n int) string {
	s := camel(name)
	if s == "" || !unicode.IsLetter(rune(s[0])) {
		s = "Param" + strconv.Itoa(n)
	}
	return s
}

func (g *gen) assemblyDecls(asms []Assembly) {
	for _, a := range asms {
		id := g.ident("Assembly", a.Name, a.Number, "%s", "%sInstance", "%sSize", "%sData", "Decode%s")
		inst, ok := a.Instance()
		g.p("// %s is Assem%d, %q.\n", id, a.Number, a.Name)
		g.p("const (\n")
		if ok {
			g.p("\t%sInstance uint32 = %d\n", id, inst)
		}
		g.p("\t%sSize int = %d\n)\n\n", id, a.Size)
		fields, size, ok := g.layout(a)
		if ok && len(fields) == 0 {
			continue
		}
		if !ok {
			if len(a.Members) > 0 {
				g.p("// %s has members that are not whole octets of numeric parameters: no struct is generated.\n\n", id)
			}
			continue
		}
		g.p("// %sData is the content of %s.\ntype %sData struct {\n", id, id, id)
		for _, f := range fields {
			g.p("\t%s %s\n", f.name, f.gt)
		}
		g.p("}\n\n")
		g.p("// Encode returns the %d octets of the assembly.\nfunc (d %sData) Encode() []byte {\n\tb := make([]byte, %d)\n", size, id, size)
		for _, f := range fields {
			g.p("\t%s\n", putField(f))
		}
		g.p("\treturn b\n}\n\n")
		g.p("// Decode%s decodes the octets of the assembly.\nfunc Decode%s(b []byte) (%sData, error) {\n\tvar d %sData\n", id, id, id, id)
		g.p("\tif len(b) != %d {\n\t\treturn d, fmt.Errorf(\"%s: %%d octets, want %d\", len(b))\n\t}\n", size, id, size)
		for _, f := range fields {
			g.p("\t%s\n", getField(f))
		}
		g.p("\treturn d, nil\n}\n\n")
	}
}

func putField(f field) string {
	at := fmt.Sprintf("b[%d:]", f.offset)
	switch f.gt {
	case "uint8":
		return fmt.Sprintf("b[%d] = d.%s", f.offset, f.name)
	case "int8":
		return fmt.Sprintf("b[%d] = byte(d.%s)", f.offset, f.name)
	case "uint16", "int16":
		return fmt.Sprintf("binary.LittleEndian.PutUint16(%s, uint16(d.%s))", at, f.name)
	case "uint32", "int32":
		return fmt.Sprintf("binary.LittleEndian.PutUint32(%s, uint32(d.%s))", at, f.name)
	case "uint64", "int64":
		return fmt.Sprintf("binary.LittleEndian.PutUint64(%s, uint64(d.%s))", at, f.name)
	case "float32":
		return fmt.Sprintf("binary.LittleEndian.PutUint32(%s, math.Float32bits(d.%s))", at, f.name)
	default:
		return fmt.Sprintf("binary.LittleEndian.PutUint64(%s, math.Float64bits(d.%s))", at, f.name)
	}
}

func getField(f field) string {
	r := fmt.Sprintf("cip.NewReader(b[%d:])", f.offset)
	switch f.gt {
	case "uint8":
		return fmt.Sprintf("d.%s = b[%d]", f.name, f.offset)
	case "int8":
		return fmt.Sprintf("d.%s = int8(b[%d])", f.name, f.offset)
	case "uint16":
		return fmt.Sprintf("d.%s = %s.Uint16()", f.name, r)
	case "int16":
		return fmt.Sprintf("d.%s = %s.Int16()", f.name, r)
	case "uint32":
		return fmt.Sprintf("d.%s = %s.Uint32()", f.name, r)
	case "int32":
		return fmt.Sprintf("d.%s = %s.Int32()", f.name, r)
	case "uint64":
		return fmt.Sprintf("d.%s = %s.Uint64()", f.name, r)
	case "int64":
		return fmt.Sprintf("d.%s = %s.Int64()", f.name, r)
	case "float32":
		return fmt.Sprintf("d.%s = %s.Float32()", f.name, r)
	default:
		return fmt.Sprintf("d.%s = %s.Float64()", f.name, r)
	}
}

// resolve returns the number a connection field means: a number, the
// default of a ParamN, or the size of an AssemN.
func (g *gen) resolve(v string) (int64, bool) {
	v = strings.TrimSpace(v)
	if v == "" {
		return 0, false
	}
	if m := reRef.FindStringSubmatch(v); m != nil {
		n, _ := strconv.Atoi(m[2])
		switch strings.ToLower(m[1]) {
		case "param":
			p, ok := g.params[n]
			if !ok {
				return 0, false
			}
			x, err := number(p.Default)
			// Out of the range of int64, the conversion is not defined.
			return int64(x), err == nil && math.Abs(x) < 1<<63
		case "assem":
			a, ok := g.asms[n]
			return int64(a.Size), ok && a.Size > 0
		}
		return 0, false
	}
	x, err := parseInt(Field{Kind: FieldToken, Value: v})
	return x, err == nil
}

// formatAssembly returns the assembly a format field references.
func (g *gen) formatAssembly(v string) (Assembly, bool) {
	m := reRef.FindStringSubmatch(strings.TrimSpace(v))
	if m == nil || !strings.EqualFold(m[1], "Assem") {
		return Assembly{}, false
	}
	n, _ := strconv.Atoi(m[2])
	a, ok := g.asms[n]
	return a, ok
}

func (g *gen) connectionDecls(conns []Connection) {
	for _, c := range conns {
		id := g.ident("Connection", c.Name, c.Number)
		var points []uint32
		var cls bool
		for _, s := range c.Path {
			l, ok := s.(cip.LogicalSegment)
			if !ok {
				continue
			}
			switch l.Type {
			case cip.LogicalClass:
				cls = cip.Class(l.Value) == cip.ClassAssembly
			case cip.LogicalInstance, cip.LogicalConnectionPoint:
				points = append(points, l.Value)
			default:
				// Members, attributes and service IDs do not name I/O points.
			}
		}
		class := c.Class()
		if !cls || (len(points) != 2 && len(points) != 3) || (class != 0 && class != 1) {
			g.p("// Connection%d, %q, has no assembly path of an I/O connection: no configuration is generated.\n\n", c.Number, c.Name)
			continue
		}
		var cfg, ot, to uint32
		if len(points) == 3 {
			cfg, ot, to = points[0], points[1], points[2]
		} else {
			ot, to = points[0], points[1]
		}
		otSize := g.sizeOf(c.OTSize, c.OTFormat)
		toSize := g.sizeOf(c.TOSize, c.TOFormat)
		rpi, ok := g.resolve(c.OTRPI)
		if !ok || rpi <= 0 || rpi > math.MaxInt64/int64(time.Microsecond) {
			rpi = 10000
		}
		g.p("// %s returns the scanner configuration of Connection%d, %q.\n", id, c.Number, c.Name)
		if c.Help != "" {
			g.p("// %s\n", goComment(c.Help))
		}
		g.p("// The RPI defaults to the EDS's O->T RPI; the real-time formats are the\n// scanner's defaults (32-bit run/idle header O->T, modeless T->O).\n")
		g.p("func %s() scanner.IOConfig {\n\treturn scanner.IOConfig{\n", id)
		if cfg != 0 {
			g.p("\t\tConfigInstance: %d,\n", cfg)
		}
		g.p("\t\tOutputInstance: %d,\n\t\tInputInstance: %d,\n\t\tOutputSize: %d,\n\t\tInputSize: %d,\n", ot, to, otSize, toSize)
		g.p("\t\tRPI: %d * time.Microsecond,\n\t\tClassZero: %v,\n\t}\n}\n\n", rpi, class == 0)
	}
}

// sizeOf returns the application size of a direction: the size field
// when it resolves, else the size of the assembly of the format field.
func (g *gen) sizeOf(size, fmtField string) int64 {
	if n, ok := g.resolve(size); ok {
		return n
	}
	if a, ok := g.formatAssembly(fmtField); ok {
		return int64(a.Size)
	}
	return 0
}
